SERVICES = [
dict(slug='creation-site-web',name='Création de site web',short='Web & mobile',verb='Construire',code='BUILD',number='01',title='Un site qui ouvre<br>les bonnes <em>portes.</em>',seo='Création de site web à Bamako, Mali | THEPEEAK',desc='Sites vitrines, e-commerce et plateformes à Bamako : design mobile, contenus, SEO technique et parcours de contact. Découvrez les livrables et préparez votre devis.',intro='Un site professionnel doit expliquer votre valeur, rassurer et faciliter la prochaine action. Nous réunissons contenu, design et développement pour donner à votre activité un point de contact qui travaille pour elle.',problem='Votre activité a grandi. Votre site, lui, est resté au point de départ.',impact='Une offre difficile à comprendre, un formulaire trop long ou une navigation inconfortable sur téléphone peut interrompre une demande avant même le premier échange.',solution='Nous dessinons le parcours autour d’une action prioritaire : obtenir un devis, réserver, commander ou accéder à un service.',deliver=['Plan des pages et hiérarchie des contenus','Maquettes adaptées au mobile et au grand écran','Site intégré, formulaires et liens WhatsApp contextualisés','Titres, descriptions, sitemap et données structurées pertinentes','Recette fonctionnelle et documentation de prise en main'],scope='Le nombre de pages, les textes à rédiger, les langues et les connexions à vos outils déterminent le périmètre. Domaine, hébergement, maintenance et abonnements externes sont identifiés séparément dans le devis.',options=[('Présenter','Site vitrine','Pour présenter une activité, ses offres et ses preuves. Pages de services, réalisations, présentation et contact.'),('Convertir','Landing page','Pour une offre ou une campagne précise. Une promesse, des réponses aux objections et une action principale.'),('Vendre ou servir','Boutique & plateforme','Pour gérer un catalogue, des commandes ou un espace connecté. Les rôles, le paiement et les intégrations sont cadrés avant le développement.')],steps=[('Cadrage','Nous définissons les publics, les pages utiles, les contenus existants et ce qu’une conversion signifie pour vous.'),('Prototype','Vous validez les textes clés et le parcours sur des maquettes, avant l’intégration.'),('Construction','Nous intégrons les pages et les fonctionnalités prévues, puis préparons le référencement technique.'),('Mise en ligne','Nous contrôlons les parcours, configurons le domaine et transmettons les accès et la documentation convenus.')],prepare='Vos offres, votre logo, vos photos autorisées, quelques exemples de sites, l’action attendue et les accès au domaine si vous en possédez déjà un.',measure='Demandes reçues, formulaires terminés, clics vers WhatsApp, lisibilité mobile et performance des pages. Les indicateurs retenus dépendent de votre objectif.',faqs=[('Combien coûte un site web au Mali ?','Le devis dépend du type de site, du nombre de pages, de la création des contenus et des fonctions à développer. Un site vitrine et une plateforme avec comptes clients demandent des travaux différents. Nous séparons la création, les options et les frais récurrents pour vous permettre de comparer.'),('Combien de temps prend la création ?','Le calendrier est proposé après le cadrage. Il tient compte des validations, de la disponibilité des textes et des visuels, des intégrations et de la recette. Nous définissons les jalons avant de démarrer.'),('Puis-je modifier mon site après livraison ?','Oui, si un espace d’administration fait partie du périmètre. Nous précisons les contenus modifiables et la prise en main au devis. Une page statique peut aussi être maintenue par le studio.'),('Peut-on intégrer Orange Money ou Wave ?','Nous étudions l’intégration selon votre pays, votre compte marchand et les API ou prestataires disponibles. Les frais du prestataire, les remboursements et les scénarios de paiement sont à cadrer séparément.'),('La création inclut-elle le SEO ?','Les fondamentaux techniques et éditoriaux convenus sont préparés dès la conception. Une stratégie de contenu et un suivi SEO continu sont des prestations distinctes. Une première place sur Google ne peut pas être garantie.'),('Qui possède le domaine et les accès ?','Le devis précise la propriété des livrables, les licences et les conditions de remise des accès. Nous recommandons que votre entreprise reste titulaire de son nom de domaine.'),('Travaillez-vous à distance ?','Oui. Le cadrage, les maquettes et les validations peuvent se faire à distance, avec un suivi écrit. Les besoins locaux, les langues et les moyens de paiement sont examinés pour chaque marché.')]),
dict(slug='marketing-seo-geo',name='Marketing digital, SEO et GEO',short='SEO & acquisition',verb='Faire grandir',code='GROW',number='02',title='Être trouvé.<br>Être compris.<br><em>Être choisi.</em>',seo='SEO, GEO et marketing digital au Mali | THEPEEAK',desc='Audit SEO, contenus utiles, visibilité dans les moteurs et réponses IA, campagnes et suivi des demandes : construisez une acquisition mesurable avec THEPEEAK.',intro='Vos futurs clients posent des questions avant de vous contacter. Nous relions leurs recherches à des pages utiles, une offre compréhensible et un parcours de conversion mesurable.',problem='Vous publiez, mais les demandes ne suivent pas.',impact='Multiplier les contenus sans intention claire peut attirer des visites peu pertinentes. Et une campagne renvoyant vers une page vague gaspille une partie de son potentiel.',solution='Nous partons des besoins de vos clients, priorisons les pages qui peuvent y répondre et suivons les demandes réelles plutôt que les seuls volumes de visites.',deliver=['Audit technique et éditorial avec priorités','Cartographie des intentions de recherche et plan de contenus','Optimisation des pages, liens internes et informations de marque','Plan de mesure des demandes et tableau de suivi','Campagnes et créations publicitaires si prévues au périmètre'],scope='Le nombre de pages, les marchés, la production éditoriale et la fréquence de suivi déterminent les honoraires. Le budget publicitaire payé aux plateformes est distinct. Aucun volume de ventes, classement ou citation IA n’est vendu comme garanti.',options=[('Comprendre','Audit & feuille de route','Repérer les freins techniques, les pages manquantes et les demandes que votre offre peut réellement satisfaire.'),('Construire dans la durée','SEO & contenus','Travailler les pages de services, les guides, le maillage et les informations de l’entreprise pour améliorer leur compréhension.'),('Activer une offre','Campagnes & conversion','Cadrer une audience, un budget, des créations et une page de destination. Ajuster à partir des demandes et de leur qualité.')],steps=[('Diagnostic','État du site, présence actuelle, offres rentables et questions commerciales récurrentes.'),('Priorisation','Choix des pages, des canaux et des indicateurs à partir de votre contexte et de vos moyens.'),('Publication','Mise en œuvre technique, contenus, pages de destination et campagnes prévues au plan.'),('Apprentissage','Lecture des résultats, retours commerciaux et ajustements des prochaines actions.')],prepare='L’adresse de votre site, vos offres prioritaires, les questions fréquentes de vos prospects, vos marchés et les accès disponibles à Search Console ou aux comptes publicitaires.',measure='Demandes qualifiées par canal, pages qui déclenchent des contacts, requêtes pertinentes et coût par demande pour les campagnes. Une hausse des impressions seule ne prouve pas une hausse des ventes.',faqs=[('Quelle différence entre SEO et GEO ?','Le SEO améliore l’accès et la compréhension des pages pour les moteurs de recherche. Le GEO vise leur compréhension et leur éventuelle utilisation dans les réponses générées par l’IA. Un contenu utile, précis, accessible et attribuable sert les deux démarches.'),('Peut-on garantir la première place sur Google ?','Non. Les résultats dépendent notamment de la concurrence, du contenu, de la réputation et des systèmes du moteur. Nous nous engageons sur les travaux, leur suivi et la transparence des résultats.'),('Quand peut-on évaluer le travail SEO ?','Les corrections techniques peuvent être constatées rapidement, mais leurs effets sur les résultats de recherche nécessitent une nouvelle exploration et du temps. La progression se suit sur plusieurs périodes comparables, en tenant compte de la saisonnalité.'),('Faut-il un fichier spécial pour apparaître dans les réponses IA ?','Pour les fonctionnalités IA de Google Search, Google ne demande ni fichier IA particulier ni balisage spécial. Les pages doivent être accessibles, indexables et utiles. Les règles varient selon les moteurs et sont à surveiller.'),('Le budget publicitaire est-il inclus ?','Il est distingué des honoraires de stratégie, création et gestion. Le devis précise qui règle les plateformes, les limites de dépense et les modalités de suivi.'),('Optimisez-vous la visibilité locale à Bamako ?','Oui, selon votre activité et son éligibilité aux services concernés : cohérence du nom, des coordonnées, des offres et des pages locales. Nous ne créons pas de fausses adresses ou de faux avis.'),('Comment savoir d’où viennent mes clients ?','Nous définissons les événements utiles et les paramètres de campagne, puis croisons les demandes avec les retours commerciaux. Les outils de suivi et le consentement sont configurés selon le dispositif retenu.')]),
dict(slug='branding-identite-visuelle',name='Branding et identité visuelle',short='Branding & identité',verb='Se distinguer',code='DEFINE',number='03',title='Une marque<br>que l’on <em>reconnaît.</em>',seo='Branding et identité visuelle à Bamako | THEPEEAK',desc='Positionnement, logo, charte graphique et supports de marque au Mali. Une identité visuelle cohérente, avec un périmètre de création et des livrables définis.',intro='Votre identité accompagne chaque rencontre avec vos clients. Nous clarifions ce que votre marque veut dire et construisons les codes visuels qui lui donnent une présence cohérente.',problem='Votre entreprise a une personnalité. Ses supports ne la racontent pas encore.',impact='Des couleurs qui changent, un logo difficile à utiliser ou un discours trop générique rendent votre offre moins reconnaissable et compliquent le travail de vos équipes.',solution='Nous partons de votre positionnement pour créer un système visuel que vous pouvez utiliser sur vos supports quotidiens.',deliver=['Synthèse du positionnement et direction créative','Logo et variantes prévues au périmètre','Palette, typographies et règles d’utilisation','Charte graphique et fichiers d’export convenus','Applications sur les supports prioritaires'],scope='La recherche de nom, les formalités de marque, les licences typographiques, l’impression et la production de contenus sont des postes à préciser. Le nombre de pistes et de cycles de corrections est fixé avant la création.',options=[('Poser le cap','Positionnement','Clarifier l’audience, la différence, le ton et les messages qui serviront de base à la création.'),('Créer les codes','Identité visuelle','Construire un logo, une palette et un langage graphique qui fonctionnent ensemble, sur papier comme sur écran.'),('Faire vivre la marque','Déploiement','Décliner l’identité sur les supports utiles : réseaux sociaux, présentation commerciale, site ou documents.')],steps=[('Écouter','Comprendre votre histoire, vos publics, votre marché et la perception à faire évoluer.'),('Explorer','Comparer des directions créatives argumentées, avec leurs usages possibles.'),('Affiner','Développer la direction retenue et vérifier sa lisibilité à différentes tailles.'),('Transmettre','Livrer les fichiers, la charte et les exemples d’application prévus pour vos équipes.')],prepare='Votre nom, votre histoire, les publics visés, les supports existants et les usages prioritaires. Si vous avez une marque déposée, les éléments autorisés pour le projet.',measure='Cohérence des supports, lisibilité du logo, facilité de réutilisation des modèles et clarté du message. La notoriété se construit ensuite par un usage régulier de cette identité.',faqs=[('Quelle différence entre un logo et une identité visuelle ?','Le logo est un signe. L’identité visuelle inclut aussi les couleurs, les typographies, les principes de composition et les applications. La charte explique comment utiliser ces éléments ensemble.'),('Pouvez-vous moderniser un logo existant ?','Oui. Nous examinons les éléments à conserver et ceux qui posent problème. Une évolution peut préserver les repères déjà connus de vos clients.'),('Quels fichiers vais-je recevoir ?','Les formats livrés sont listés au devis : par exemple fichiers vectoriels pour l’impression et exports pour le web. Les variantes couleur et monochrome sont définies selon vos usages.'),('Combien de propositions et de retours sont inclus ?','Le nombre de pistes et de cycles de retours est défini au cadrage. Cela permet de concentrer les échanges et d’éviter les corrections sans fin.'),('Les droits et licences sont-ils inclus ?','Le contrat précise les droits d’utilisation et de cession sur les créations. Les polices, photos et autres éléments tiers conservent leurs conditions de licence.'),('Créez-vous les supports imprimés ?','Nous pouvons préparer les fichiers des supports convenus. L’impression, les quantités, le papier et les conditions de livraison doivent faire l’objet d’un périmètre distinct.'),('Peut-on commander l’identité avant le site ?','Oui. Définir les codes de marque en premier permet de concevoir ensuite un site et des supports cohérents.')]),
dict(slug='hebergement-maintenance',name='Hébergement et maintenance',short='Hébergement & suivi',verb='Fiabiliser',code='SCALE',number='04',title='Un site en ligne.<br>Un suivi <em>dans la durée.</em>',seo='Hébergement et maintenance web au Mali | THEPEEAK',desc='Maintenance, sauvegardes, mises à jour et suivi de site web au Mali. Définissez les responsabilités, les interventions et les besoins de restauration avec THEPEEAK.',intro='La mise en ligne est un début. Nous organisons l’hébergement et le suivi de votre site pour que les accès, les mises à jour et les interventions restent maîtrisés.',problem='Un site sans suivi devient une dépendance que personne ne pilote.',impact='Un renouvellement oublié, une extension vieillissante ou une sauvegarde inutilisable peut perturber vos échanges avec les clients et allonger la reprise.',solution='Nous commençons par un état des lieux, puis définissons un plan de suivi avec des responsabilités, des accès et des procédures explicites.',deliver=['État des lieux de l’hébergement et des accès','Plan de sauvegarde et de restauration défini','Mises à jour et contrôles selon le contrat','Suivi des incidents et compte rendu des interventions','Recommandations pour les évolutions nécessaires'],scope='La fréquence des sauvegardes, leur rétention, les plages de support, les délais d’intervention et le volume de modifications sont contractualisés. L’hébergement, les licences et les renouvellements sont détaillés. Aucun service 24 h/24 n’est implicite.',options=[('Reprendre la maîtrise','Audit & reprise','Inventaire du site, du domaine, des accès, des dépendances et des risques de migration.'),('Entretenir','Maintenance préventive','Mises à jour, contrôles de fonctionnement et sauvegardes selon un planning convenu.'),('Accompagner','Suivi & évolutions','Traitement des demandes et petites évolutions dans un volume défini, avec historique des interventions.')],steps=[('Inventaire','Cartographier domaine, hébergement, messagerie, logiciels et propriétaires des comptes.'),('Préparation','Définir les sauvegardes, les accès et la marche à suivre en cas de problème.'),('Intervention','Réaliser les opérations convenues et contrôler les parcours sensibles après modification.'),('Suivi','Documenter les changements, les points de vigilance et les prochaines échéances.')],prepare='L’adresse du site, la plateforme utilisée, les accès administrateur disponibles, le nom du fournisseur d’hébergement et les difficultés rencontrées.',measure='Interventions réalisées, incidents rencontrés, état des sauvegardes et échéances de renouvellement. Les objectifs de disponibilité et de restauration sont définis au contrat.',faqs=[('Pouvez-vous reprendre un site créé ailleurs ?','Oui, après un diagnostic de sa technologie, des accès et de son état. Certaines reprises nécessitent d’abord une remise à niveau ou une migration.'),('Quelle différence entre hébergement et maintenance ?','L’hébergement fournit l’infrastructure qui sert le site. La maintenance concerne son suivi, ses mises à jour, ses contrôles et les interventions prévues au contrat.'),('Les sauvegardes sont-elles incluses ?','Le contrat précise le contenu sauvegardé, la fréquence, la rétention, le lieu de stockage et les modalités de restauration. Leur simple existence ne suffit pas : la reprise doit être préparée.'),('Intervenez-vous à toute heure ?','Les plages de support et les délais d’intervention sont explicitement convenus. Nous ne présentons pas une astreinte permanente comme incluse par défaut.'),('Pouvez-vous garantir qu’un site ne sera jamais piraté ?','Non. Les mises à jour, les accès limités, les sauvegardes et la surveillance réduisent certains risques, sans supprimer toute possibilité d’incident.'),('Puis-je garder mon fournisseur actuel ?','Oui si son environnement convient au site et au suivi demandé. Une migration est proposée lorsque le diagnostic la justifie.'),('Les nouvelles pages sont-elles comprises ?','Les créations de pages et changements fonctionnels sont distingués de la maintenance. Un volume d’évolutions peut être prévu dans l’accompagnement.')]),
dict(slug='visuels-video-ia',name='Visuels et vidéos IA',short='Visuels & vidéo IA',verb='Faire ressentir',code='CREATE',number='05',title='Des idées que<br>l’on a envie de <em>regarder.</em>',seo='Création de visuels et vidéos IA au Mali | THEPEEAK',desc='Direction artistique, visuels de marque et vidéos IA pour vos campagnes au Mali. Découvrez le processus créatif, les formats, les droits et les livrables.',intro='Une création doit faire comprendre une offre autant qu’elle attire le regard. Nous associons direction artistique et outils de génération pour concevoir des visuels cohérents avec votre marque.',problem='Vos contenus se ressemblent, alors que votre offre mérite sa propre expression.',impact='Des images génériques ou des vidéos sans message clair peuvent capter un instant d’attention sans aider votre public à comprendre ce que vous proposez.',solution='Nous définissons un angle, une intention visuelle et un format avant de produire. Les outils IA servent une direction créative, puis les éléments sont sélectionnés et affinés.',deliver=['Brief créatif, angle et direction visuelle','Storyboard ou intentions de composition selon le format','Visuels ou séquences sélectionnés et finalisés','Déclinaisons aux formats convenus','Exports et conditions d’utilisation explicités'],scope='Le nombre de créations, les durées, les formats, les langues, la voix, la musique et les cycles de corrections sont cadrés. Une scène générée peut demander plusieurs essais. Les droits sur les éléments fournis et les outils employés sont examinés.',options=[('Arrêter le regard','Visuels de campagne','Images de marque, mises en scène de produits et compositions destinées à une offre précise.'),('Raconter','Vidéo & motion','Un déroulé court, un message et une progression visuelle pour présenter une activité ou une campagne.'),('Décliner','Kit de contenus','Adapter une direction créative à plusieurs formats, pour le site et les réseaux choisis.')],steps=[('Intention','Fixer l’offre, le public, le message central et l’action attendue.'),('Direction','Valider les références, le storyboard, le ton et les contraintes de la marque.'),('Production','Générer, sélectionner, monter et corriger les éléments utiles au récit.'),('Déclinaisons','Adapter les créations aux dimensions et aux usages prévus, puis transmettre les exports.')],prepare='Votre charte, les produits ou services à mettre en avant, les images dont vous avez les droits, les canaux de diffusion et les mentions obligatoires.',measure='Lisibilité du message, cohérence de marque, attention et actions obtenues selon le canal. Les résultats d’une publicité dépendent aussi de son ciblage, de son budget et de la page de destination.',faqs=[('Quels formats pouvez-vous produire ?','Des visuels pour le web et les réseaux, des séquences vidéo et des déclinaisons de campagne. Les dimensions, la durée et les variantes sont fixées dans le brief.'),('Est-ce possible de montrer mon produit fidèlement ?','La génération peut altérer les détails, les inscriptions ou les proportions. Pour un produit qui exige une reproduction exacte, nous définissons les éléments à conserver à partir de vos photos et les étapes de validation.'),('L’IA remplace-t-elle une séance photo ?','Pas dans tous les cas. Des images réelles restent préférables pour prouver un résultat, présenter une équipe ou documenter un produit. Nous choisissons l’approche selon l’usage.'),('Puis-je utiliser les créations en publicité ?','Les usages commerciaux sont cadrés au devis en fonction des éléments et des outils employés. Les images, marques, musiques et voix tierces doivent disposer des droits nécessaires.'),('Combien de corrections sont possibles ?','Le nombre de retours et les validations intermédiaires sont convenus avant la production. Un changement complet de direction peut modifier le périmètre.'),('Pouvez-vous ajouter une voix et des sous-titres ?','Oui, si ces éléments sont prévus : script, langue, voix autorisée, sous-titrage et versions de diffusion sont définis ensemble.'),('Les visuels générés constituent-ils des preuves client ?','Non. Ils peuvent illustrer un concept ou une campagne, mais ne doivent pas être présentés comme une réalisation réelle, un témoignage ou un résultat mesuré s’ils ne le sont pas.')]),
dict(slug='logiciels-metier',name='Logiciel métier',short='Logiciels & automatisation',verb='Simplifier',code='SOFTWARE',number='06',title='Moins de ressaisie.<br>Plus de <em>maîtrise.</em>',seo='Logiciels métier, CRM et automatisation au Mali | THEPEEAK',desc='CRM, tableaux de bord, espaces clients et automatisation sur mesure au Mali. Un logiciel construit autour de vos opérations, de vos rôles et de vos données.',intro='Quand les fichiers, les messages et les outils ne se parlent plus, le travail se disperse. Nous concevons des applications qui réunissent les bonnes informations et simplifient les opérations utiles.',problem='Vos équipes consacrent trop de temps à relier les informations.',impact='Une commande recopiée, une validation oubliée ou des droits mal définis peuvent créer des erreurs et rendre difficile le suivi des dossiers.',solution='Nous cartographions un processus réel, choisissons un périmètre utile et construisons une première version que vos équipes peuvent prendre en main.',deliver=['Cartographie du processus et spécifications prioritaires','Prototype des écrans et règles métier','Application avec rôles et accès définis','Connexions et automatisations prévues au périmètre','Recette, documentation et prise en main'],scope='Le nombre de profils, les règles métier, la migration des données, les intégrations et les volumes structurent le coût. Les abonnements, coûts d’API et besoins de maintenance sont identifiés. Un outil existant peut être recommandé si le sur-mesure n’est pas pertinent.',options=[('Suivre les relations','CRM & espace client','Centraliser les contacts, demandes, documents et prochaines actions dans un parcours adapté à vos équipes.'),('Piloter les opérations','Gestion & tableaux de bord','Suivre dossiers, commandes, activités ou indicateurs à partir de données définies et accessibles.'),('Relier les outils','Automatisation','Réduire les transferts manuels et organiser les alertes, validations ou connexions aux services existants.')],steps=[('Observer','Décrire le processus actuel avec les personnes qui l’utilisent, ses exceptions et ses contraintes.'),('Prototyper','Valider les écrans, les rôles et les règles avant de développer les fonctions prioritaires.'),('Développer','Construire par étapes, intégrer les données et vérifier les permissions et les scénarios métier.'),('Déployer','Organiser la reprise, la prise en main et le retour terrain pour prioriser les évolutions.')],prepare='Un exemple de processus, les fichiers utilisés avec données anonymisées, les profils des utilisateurs, les outils à connecter et les contraintes de confidentialité.',measure='Temps de traitement, erreurs de saisie, dossiers suivis et adoption par les équipes. Nous définissons une situation de départ avant de chercher à mesurer un gain.',faqs=[('Sur mesure ou logiciel existant : comment choisir ?','Nous comparons vos règles, vos intégrations et votre budget aux outils disponibles. Si un logiciel existant répond au besoin, sa configuration peut être plus adaptée qu’un développement complet.'),('Peut-on commencer par une petite version ?','Oui. Une première version peut couvrir un seul processus et un groupe limité d’utilisateurs, puis évoluer après les retours terrain.'),('Comment sont gérés les droits des utilisateurs ?','Nous définissons les profils et les opérations autorisées. Les permissions doivent être appliquées côté serveur ou base de données, et pas seulement par des boutons masqués.'),('Peut-on reprendre mes fichiers Excel ?','Une importation est étudiée après examen de la qualité, du format et du volume des données. La préparation, les correspondances et les contrôles sont inclus dans un périmètre explicite.'),('Mes outils actuels peuvent-ils être connectés ?','Cela dépend de leurs API, de leurs droits d’accès et de leurs conditions. Les limites, les coûts et les scénarios d’erreur sont étudiés avant de confirmer une connexion.'),('Un logiciel peut-il fonctionner sans connexion ?','Certains usages peuvent prévoir un fonctionnement hors ligne et une synchronisation. C’est une contrainte de conception à exprimer dès le départ, pas une option automatique.'),('Comment évolue le logiciel après livraison ?','Le suivi, la correction d’incidents et les nouvelles fonctions sont définis dans les conditions d’accompagnement. Les accès, la documentation et les responsabilités de maintenance sont précisés.')])]
